  'Find upcoming initiatives near you and join the ones that suit you.': { mr: 'जवळचे आगामी उपक्रम शोधा आणि योग्य उपक्रमात सहभागी व्हा.', hi: 'अपने आसपास के आगामी उपक्रम खोजें और उपयुक्त उपक्रम में शामिल हों।' },
  'Find nearby initiatives': { mr: 'जवळचे उपक्रम शोधा', hi: 'आसपास के उपक्रम खोजें' },
