  'Once filed, the complaint wording and frozen route facts cannot be edited.': { mr: 'दाखल केल्यानंतर तक्रारीचा मजकूर आणि निश्चित मार्ग तथ्ये बदलता येत नाहीत.', hi: 'दर्ज होने के बाद शिकायत का शब्दांकन और स्थिर मार्ग तथ्य बदले नहीं जा सकते।' },
  'View report timeline': { mr: 'अहवालाचा घटनाक्रम पाहा', hi: 'रिपोर्ट की समयरेखा देखें' },
  'MY ACTIONS': { mr: 'माझ्या कृती', hi: 'मेरे कार्य' },
  'Your saved civic work': { mr: 'तुमचे जतन केलेले नागरी काम', hi: 'आपका सहेजा नागरिक कार्य' },
  'Drafts can be resumed. Filed reports open as immutable records.': { mr: 'मसुदे पुन्हा सुरू करता येतात. दाखल अहवाल बदलता न येणाऱ्या नोंदी म्हणून उघडतात.', hi: 'मसौदे फिर शुरू किए जा सकते हैं। दर्ज रिपोर्टें अपरिवर्तनीय रिकॉर्ड के रूप में खुलती हैं।' },
  'Only you can see your drafts. Filed reports can’t be changed.': { mr: 'तुमचे मसुदे फक्त तुम्ही पाहू शकता. दाखल अहवाल बदलता येत नाहीत.', hi: 'आपके मसौदे केवल आप देख सकते हैं। दर्ज रिपोर्टें बदली नहीं जा सकतीं।' },
  'Refresh': { mr: 'ताजे करा', hi: 'रीफ़्रेश करें' },
  'No reports are saved for this anonymous account.': { mr: 'या अनामिक खात्यासाठी कोणताही अहवाल जतन केलेला नाही.', hi: 'इस गुमनाम खाते के लिए कोई रिपोर्ट सहेजी नहीं गई है।' },
  'No reports are saved for this profile.': { mr: 'या प्रोफाइलसाठी कोणतेही अहवाल जतन केलेले नाहीत.', hi: 'इस प्रोफ़ाइल के लिए कोई रिपोर्ट सहेजी नहीं गई है।' },
  'Sign in to view your saved civic work.': { mr: 'तुमचे जतन केलेले नागरी काम पाहण्यासाठी साइन इन करा.', hi: 'अपना सहेजा नागरिक कार्य देखने के लिए साइन इन करें।' },
  "Signing out doesn't delete anything.": { mr: 'साइन आउट केल्याने काहीही हटवले जात नाही.', hi: 'साइन आउट करने से कुछ भी नहीं मिटता।' },
  'Your saved work stays attached to your Google account — sign in to see it.': { mr: 'तुमचे जतन केलेले काम तुमच्या Google खात्याशी जोडलेले राहते — ते पाहण्यासाठी साइन इन करा.', hi: 'आपका सहेजा कार्य आपके Google खाते से जुड़ा रहता है — उसे देखने के लिए साइन इन करें।' },
  'Signed in. No saved reports yet.': { mr: 'साइन इन झाले. अद्याप कोणतेही जतन केलेले अहवाल नाहीत.', hi: 'साइन इन हो गया। अभी कोई सहेजी हुई रिपोर्ट नहीं है।' },
  'Create a report to save an owner-protected draft.': { mr: 'तुमच्यासाठी संरक्षित मसुदा जतन करण्यासाठी अहवाल तयार करा.', hi: 'अपने लिए सुरक्षित मसौदा सहेजने हेतु रिपोर्ट बनाएँ।' },
  'Create a report to keep a draft only you can see.': { mr: 'फक्त तुम्हाला दिसणारा मसुदा ठेवण्यासाठी अहवाल तयार करा.', hi: 'केवल आपको दिखने वाला मसौदा रखने के लिए रिपोर्ट बनाएँ।' },
  'No reports are saved for this device-only account.': { mr: 'या फक्त-डिव्हाइस खात्यासाठी कोणताही अहवाल जतन केलेला नाही.', hi: 'इस केवल-डिवाइस खाते के लिए कोई रिपोर्ट सहेजी नहीं गई है।' },
